DELETE FROM `lunar_product_associations` WHERE `product_parent_id` IN (1, 2, 3, 4, 5, 6, 7) OR `product_target_id` IN (1, 2, 3, 4, 5, 6, 7);
DELETE FROM `lunar_product_product_option` WHERE `product_id` IN (1, 2, 3, 4, 5, 6, 7);
DELETE FROM `product_faqs` WHERE `product_id` IN (1, 2, 3, 4, 5, 6, 7);
